#define _POSIX_C_SOURCE 200809L
#include <stdio.h>

static int is_wordsep(unsigned char c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\v' || c == '\f' || c == '\r';
}

int main(void) {
    intmax_t lines = 0;
    intmax_t words = 0;
    intmax_t bytes = 0;
    intmax_t max_line = 0;
    intmax_t cur_line = 0;
    int in_word = 0;

    for (int c; (c = getchar()) != EOF; ) {
        unsigned char ch = (unsigned char)c;
        bytes++;

        /* maxlen tracking */
        if (!is_wordsep(ch)) {
            cur_line++;
        }
        if (ch == '\n') {
            if (cur_line > max_line)
                max_line = cur_line;
            /* \r within a line doesn't affect maxlen counting beyond above;
               for a line ending with \r\n we want only the part before \n counted.
               Actually per spec: "A \r is an ordinary byte for maxlen", meaning it's counted like any other byte.
               cur_line already includes \r bytes as non-space-non-newline below. */
            if (cur_line > max_line)
                max_line = cur_line;

            lines++;
            cur_line = 0;
        } else if (ch == '\r') {
            /* keep going — it's part of the current line for maxlen */
        }

        /* word tracking: \n never starts a new space within a line, but since we reset per-word above via is_wordsep check, \n already returns true from is_wordsep.
           We treat any wordsep (including \r) as word separators which is correct except \r within a line is just bytes. */

        if (is_wordsep(ch)) {
            in_word = 0;
        } else if (!in_word) {
            words++;
            in_word = 1;
        }
    }

    /* Handle last line that may not end with \n */
    if (bytes > 0 && cur_line > max_line)
        max_line = cur_line;

    printf("%jd %jd %jd %jd\n", lines, words, bytes, max_line);
    return 0;
}

